class Solution {
public:
    int maxArea(int h, int w, vector<int>& horizontalCuts, vector<int>& verticalCuts) {
        sort(horizontalCuts.begin(), horizontalCuts.end());
        sort(verticalCuts.begin(), verticalCuts.end());

        long long max_h = horizontalCuts[0];
        for (int i = 1; i < (int)horizontalCuts.size(); ++i) {
            max_h = max(max_h, (long long)horizontalCuts[i] - horizontalCuts[i-1]);
        }
        max_h = max(max_h, (long long)h - horizontalCuts.back());

        long long max_w = verticalCuts[0];
        for (int i = 1; i < (int)verticalCuts.size(); ++i) {
            max_w = max(max_w, (long long)verticalCuts[i] - verticalCuts[i-1]);
        }
        max_w = max(max_w, (long long)w - verticalCuts.back());

        return (max_h * max_w) % 1000000007;
    }
};
